window.addEventListener('load',()=>{
 Progress.load(Progress.freshProfile());Progress.completeTutorial();Progress.profile.challenges={unlocked:true,available:15,won:[1,2],completed:['veterans'],selected:['heavydeck','bag','cursed']};Progress.profile.insignia=10;Progress.profile.advantages=['travel_relic','full_purse','pretraining','planned_hand'];I18n.set(parent.qaLang);S=null;home();
 const mode=parent.qaMode;if(mode==='milestones'||mode==='milestones-open'){if(mode==='milestones-open'){Progress.profile.decks=G.DECKS.map(d=>d.id);Progress.profile.blackfangUnlocked=true;Progress.profile.dawncrestUnlocked=true;Progress.profile.orderGateVersion=1;JourneyMilestones.facts().wonDecks=['vanguard'];JourneyMilestones.facts().bossMaps={blackfang:[1,2]};Progress.check();}milestonesView();return;}if(mode==='portraits'){deckSelect();deckPreview('vanguard');return;}if(mode==='milestone-payout'){Progress.profile.advantages=JourneyAdvantages.LIST.slice(0,5).map(a=>a.id);milestonesView();return;}if(mode==='tour'||mode==='tour-locked'){Progress.profile.stats.runs=1;Progress.profile.onboarding.menuSeen=false;Progress.profile.challenges.unlocked=mode==='tour';home();return;}function fresh(){S=G.fresh('vanguard',975);S.plannedHandChoice='warrior';S.runSetupConfirmed=true;JourneyChallenges.start(S);}
 if(mode.startsWith('ib-')){fresh();const id=mode==='ib-regular'?'ib_hartlord':'ib_wayfarer';S.journey.act=id==='ib_wayfarer'?3:1;S.journey.history=id==='ib_wayfarer'?[{act:1,order:'ironbound',route:[]},{act:2,order:'ironbound',route:[]}]:[];S.layer=14;S.route=S.map.slice(0,14).map(row=>row[0].id);const n=S.map[14][0];G.prepareRouteNode(S,n);n.bossId=id;G.enter(S,n.id);if(mode==='ib-two'){S.bossEncounter.form=2;JourneyRaid.initialize(S,'true_ib_wayfarer',{hp:1,damage:1,minions:1},true);S.round=4;}render();if(mode==='ib-info')document.querySelector('[data-act=boss-info]')?.click();if(mode==='ib-card')openDetail('hero_ib_wayfarer','roster');return;}
 if(mode==='setup'){S=G.fresh('vanguard',975);render();}
 else if(mode==='advantages')document.querySelector('[data-act=cp2-advantages]').click();
 else if(mode==='deck'||mode==='card'){deckSelect();deckPreview('balanced');if(mode==='card')openDetail('fighter','preview');}
 else if(['shop','market','run-deck','relic','evidence','unlocks','lockedmenu','recruit'].includes(mode)){fresh();S.phase='shop';S.current={id:'qa-shop',type:'shop',name:'QA Market'};S.gold=1000;S.offers={cards:['warrior','lancer','fighter','ranger'],artifacts:G.ARTIFACTS.slice(0,2).map(a=>a.id)};if(mode==='relic'||mode==='evidence'){S.phase='relic';S.offers=['shield','tome','profane_idol'];}else if(mode==='recruit'){S.phase='recruit';S.offers=['priestess','shaolin','archer'];}render();if(mode==='shop')shopServiceView('upgrade');if(mode==='run-deck')deckModal();if(mode==='unlocks'){S.meta.unlocks=[{kind:'card',id:'warrior'},{kind:'relic',id:'boots'},{kind:'booster',id:'east'},{kind:'deck',id:'vanguard'}];metaNotices();}if(mode==='lockedmenu'){Progress.profile.challenges.unlocked=false;journeyMenu();}}
 else if(mode==='enemy'||mode.startsWith('raid')){fresh();G.enter(S,G.available(S)[0].id);if(mode.startsWith('raid'))JourneyRaid.initialize(S,mode.split('-')[1]||'tree',{hp:1,damage:1,minions:1},true);S.board[10]=S.hand.shift();const b=G.createBattle(S);G.finish(S,'loss');G.nextRound(S);if(mode.startsWith('raid')){S.round=4;S.previousEnemyFormation.round=3;}S=JSON.parse(JSON.stringify(S));render();}
 if(parent.qaMode==='evidence'||parent.qaMode==='enemy'||parent.qaMode.startsWith('raid')||parent.qaMode==='card')return;
 const seedScroll=document.createElement('button');seedScroll.textContent='QA: position scroll';seedScroll.id='qa-scroll';seedScroll.style='position:fixed;left:0;top:0;z-index:99999';seedScroll.onclick=()=>requestAnimationFrame(()=>{const content=(document.querySelector('#overlay .journey-panel-content,#overlay .deck-preview-scroll')||document.querySelector('#screen-content'));content.scrollTop=Math.min(mode==='deck'?10000:500,content.scrollHeight-content.clientHeight);JourneyMenuScroll.capture();seedScroll.textContent='QA scroll '+content.scrollTop;});document.body.append(seedScroll);
 const act=document.createElement('button');act.id='qa-action';act.textContent='QA: select in place';act.style='position:fixed;left:0;top:32px;z-index:99999';act.onclick=()=>{const sc=document.querySelector('#overlay .journey-panel-content,#overlay .deck-preview-scroll')||document.querySelector('#screen-content');const before=sc.scrollTop;const b=mode==='shop'?document.querySelector('[data-act=service-confirm][data-id=p8]'):mode==='run-deck'?document.querySelector('[data-act=traits54-run][data-id=Unyielding]'):mode==='deck'?document.querySelector('[data-act=traits54-preview][data-id=Unyielding]'):document.querySelector(mode==='setup'?'[data-act=cp2-toggle][data-id=raidfury]':'[data-act=cp2-buy][data-id=flex_prep]');b.click();requestAnimationFrame(()=>{act.textContent='QA before '+before;});};document.body.append(act);
});
